def getNetworkErrors(sessionId, eventType=None, url=None, httpStatusMin=None, httpStatusMax=None, since=None, until=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0025000" if __import__("os").path.isdir("./environment_mix/0025000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getNetworkErrors"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, str):
            return _parse_rfc3339(v)
        return None

    def _log_call(status_code):
        try:
            req = _load("request_logs.json")
            if not isinstance(req, list):
                req = []
            req.append({
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "service": "BrowserTools",
                "endpoint": endpoint,
                "credential_id": None,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", req)
        except Exception:
            pass

    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sessionId.", field="sessionId")

    if eventType is not None:
        if not isinstance(eventType, str) or eventType not in ["network.request", "network.response", "network.failure"]:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid eventType.", field="eventType")

    if url is not None and not isinstance(url, str):
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid url.", field="url")

    for fld, v in [("httpStatusMin", httpStatusMin), ("httpStatusMax", httpStatusMax)]:
        if v is not None:
            if not isinstance(v, int) or v < 0 or v > 999:
                _log_call("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Invalid {fld}; must be 0..999.", field=fld)
    if httpStatusMin is not None and httpStatusMax is not None and httpStatusMin > httpStatusMax:
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "httpStatusMin must be <= httpStatusMax.", field="httpStatusMin")

    if sort is None:
        sort = "-timestamp"
    if not isinstance(sort, str) or sort not in ["timestamp", "-timestamp"]:
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1..500.", field="limit")

    since_dt = None
    until_dt = None
    if since is not None:
        since_dt = _parse_rfc3339(since)
        if since_dt is None:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid since; must be RFC 3339 date-time.", field="since")
    if until is not None:
        until_dt = _parse_rfc3339(until)
        if until_dt is None:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid until; must be RFC 3339 date-time.", field="until")
    if since_dt is not None and until_dt is not None and since_dt > until_dt:
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "since must be <= until.", field="since")

    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            cursor_obj = json.loads(raw)
            if not isinstance(cursor_obj, dict):
                raise ValueError("bad cursor")
            if cursor_obj.get("v") != 1:
                raise ValueError("bad cursor version")
            if cursor_obj.get("sessionId") != sessionId:
                raise ValueError("cursor/session mismatch")
            if cursor_obj.get("sort") != sort:
                raise ValueError("cursor/sort mismatch")
            if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
                raise ValueError("bad offset")
            sig = cursor_obj.get("sig")
            expected_sig = {
                "eventType": eventType,
                "url": url,
                "httpStatusMin": httpStatusMin,
                "httpStatusMax": httpStatusMax,
                "since": since,
                "until": until,
            }
            if sig != expected_sig:
                raise ValueError("cursor/filter mismatch")
        except Exception:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    sessions = _load("browser_sessions.json")
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
    if sess is None:
        _log_call("NOT_FOUND")
        return _err("NOT_FOUND", "Session not found.", field="sessionId")

    logs = _load("browser_logs.json")
    filtered = []
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("session_id") != sessionId:
            continue
        if r.get("source") != "network":
            continue
        # "network errors": include level=error OR event_type=network.failure OR http_status>=400 (if present)
        lvl = r.get("level")
        et = r.get("event_type")
        hs = r.get("http_status")
        is_err = (lvl == "error") or (et == "network.failure") or (isinstance(hs, int) and hs >= 400)
        if not is_err:
            continue

        if eventType is not None and et != eventType:
            continue
        if url is not None and r.get("url") != url:
            continue
        if httpStatusMin is not None:
            if not isinstance(hs, int) or hs < httpStatusMin:
                continue
        if httpStatusMax is not None:
            if not isinstance(hs, int) or hs > httpStatusMax:
                continue

        ts = _dt_from_row(r.get("timestamp"))
        if ts is None:
            continue
        if since_dt is not None and ts < since_dt:
            continue
        if until_dt is not None and ts > until_dt:
            continue

        filtered.append(r)

    reverse = (sort == "-timestamp")
    def _key(r):
        ts = r.get("timestamp")
        rid = r.get("id") or ""
        return (ts or "", rid)
    filtered.sort(key=_key, reverse=reverse)

    total = len(filtered)
    offset = cursor_obj["offset"] if cursor_obj else 0
    if offset > total:
        offset = total
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {
            "v": 1,
            "sessionId": sessionId,
            "sort": sort,
            "offset": next_offset,
            "sig": {
                "eventType": eventType,
                "url": url,
                "httpStatusMin": httpStatusMin,
                "httpStatusMax": httpStatusMax,
                "since": since,
                "until": until,
            },
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")

    _log_call("OK")
    return {
        "session_id": sessionId,
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "sort": sort,
        "filters": {
            "source": "network",
            "errors_only": True,
            "eventType": eventType,
            "url": url,
            "httpStatusMin": httpStatusMin,
            "httpStatusMax": httpStatusMax,
            "since": since,
            "until": until,
        }
    }

