        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, str):
            return _parse_rfc3339(v)
        return None

    def _log_call(status_code):
        try:
            req = _load("request_logs.json")
            if not isinstance(req, list):
                req = []
            req.append({
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "service": "BrowserTools",
                "endpoint": endpoint,
                "credential_id": None,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", req)
        except Exception:
            pass

    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sessionId.", field="sessionId")

    if level is not None:
        if not isinstance(level, str) or level not in ["debug", "info", "warning", "error"]:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid level.", field="level")

    if eventType is not None:
        if not isinstance(eventType, str) or eventType not in ["network.request", "network.response", "network.failure"]:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid eventType.", field="eventType")

    if url is not None and not isinstance(url, str):
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid url.", field="url")

    if httpMethod is not None and not isinstance(httpMethod, str):
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid httpMethod.", field="httpMethod")

    if requestId is not None and not isinstance(requestId, str):
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid requestId.", field="requestId")

    if httpStatus is not None:
        if not isinstance(httpStatus, int) or httpStatus < 0 or httpStatus > 999:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid httpStatus; must be 0..999.", field="httpStatus")

    if sort is None:
        sort = "-timestamp"
    if not isinstance(sort, str) or sort not in ["timestamp", "-timestamp"]:
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1..500.", field="limit")

    since_dt = None
    until_dt = None
    if since is not None:
        since_dt = _parse_rfc3339(since)
        if since_dt is None:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid since; must be RFC 3339 date-time.", field="since")
    if until is not None:
        until_dt = _parse_rfc3339(until)
        if until_dt is None:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid until; must be RFC 3339 date-time.", field="until")
    if since_dt is not None and until_dt is not None and since_dt > until_dt:
        _log_call("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "since must be <= until.", field="since")

    cursor_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            cursor_obj = json.loads(raw)
            if not isinstance(cursor_obj, dict):
                raise ValueError("bad cursor")
            if cursor_obj.get("v") != 1:
                raise ValueError("bad cursor version")
            if cursor_obj.get("sessionId") != sessionId:
                raise ValueError("cursor/session mismatch")
            if cursor_obj.get("sort") != sort:
                raise ValueError("cursor/sort mismatch")
            if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
                raise ValueError("bad offset")
            sig = cursor_obj.get("sig")
            expected_sig = {
                "level": level,
                "eventType": eventType,
                "url": url,
                "httpMethod": httpMethod,
                "httpStatus": httpStatus,
                "requestId": requestId,
                "since": since,
                "until": until,
            }
            if sig != expected_sig:
                raise ValueError("cursor/filter mismatch")
        except Exception:
            _log_call("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    sessions = _load("browser_sessions.json")
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
    if sess is None:
        _log_call("NOT_FOUND")
        return _err("NOT_FOUND", "Session not found.", field="sessionId")

    logs = _load("browser_logs.json")
    filtered = []
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("session_id") != sessionId:
            continue
        if r.get("source") != "network":
            continue
        if level is not None and r.get("level") != level:
            continue
        if eventType is not None and r.get("event_type") != eventType:
            continue
        if url is not None and r.get("url") != url:
            continue
        if httpMethod is not None and r.get("http_method") != httpMethod:
            continue
        if httpStatus is not None and r.get("http_status") != httpStatus:
            continue
        if requestId is not None and r.get("request_id") != requestId:
            continue

        ts = _dt_from_row(r.get("timestamp"))
        if ts is None:
            continue
        if since_dt is not None and ts < since_dt:
            continue
        if until_dt is not None and ts > until_dt:
            continue

        filtered.append(r)

    reverse = (sort == "-timestamp")
    def _key(r):
        ts = r.get("timestamp")
        rid = r.get("id") or ""
        return (ts or "", rid)
    filtered.sort(key=_key, reverse=reverse)

    total = len(filtered)
    offset = cursor_obj["offset"] if cursor_obj else 0
    if offset > total:
        offset = total
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {
            "v": 1,
            "sessionId": sessionId,
            "sort": sort,
            "offset": next_offset,
            "sig": {
                "level": level,
                "eventType": eventType,
                "url": url,
                "httpMethod": httpMethod,
                "httpStatus": httpStatus,
                "requestId": requestId,
                "since": since,
                "until": until,
            },
        }
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")

    _log_call("OK")
    return {
        "session_id": sessionId,
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "sort": sort,
        "filters": {
            "level": level,
            "eventType": eventType,
            "url": url,
            "httpMethod": httpMethod,
            "httpStatus": httpStatus,
            "requestId": requestId,
            "since": since,
            "until": until,
        }
    }

def takeScreenshot(sessionId, fullPage=None, format=None, quality=None, storageBackend=None, includeBase64=None, **_extra):
    import json, os, datetime, re, base64, uuid, time, random, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0025000" if __import__("os").path.isdir("./environment_mix/0025000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- usage/audit logging (best-effort; must not crash tool) ----
    def _log_call(status, code=None, message=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": "bt_req_" + uuid.uuid4().hex[:24],
            "service": "BrowserTools",
            "tool": "takeScreenshot",
            "timestamp": now,
            "status": status,
            "latency_ms": latency_ms,
            "session_id": sessionId,
            "error_code": code,
            "error_message": message,
            "meta": meta or {}
        }
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list): reqs = []
        reqs.append(entry)
        _save("request_logs.json", reqs)

    # ---- validation ----
    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        _log_call("error", "VALIDATION_ERROR", "sessionId is invalid")
        return _err("VALIDATION_ERROR", "sessionId is invalid")
    if fullPage is not None and not isinstance(fullPage, bool):
        _log_call("error", "VALIDATION_ERROR", "fullPage must be a boolean")
        return _err("VALIDATION_ERROR", "fullPage must be a boolean")
    if includeBase64 is not None and not isinstance(includeBase64, bool):
        _log_call("error", "VALIDATION_ERROR", "includeBase64 must be a boolean")
        return _err("VALIDATION_ERROR", "includeBase64 must be a boolean")
    if format is not None:
        if not isinstance(format, str) or format not in ("png", "jpeg"):
            _log_call("error", "VALIDATION_ERROR", "format must be one of png|jpeg")
            return _err("VALIDATION_ERROR", "format must be one of png|jpeg")
    else:
        format = "png"
    if storageBackend is not None:
        if not isinstance(storageBackend, str) or storageBackend not in ("inline", "s3", "local_fs"):
            _log_call("error", "VALIDATION_ERROR", "storageBackend must be one of inline|s3|local_fs")
            return _err("VALIDATION_ERROR", "storageBackend must be one of inline|s3|local_fs")
    else:
        storageBackend = "inline"

    if quality is not None:
        if not isinstance(quality, int) or quality < 1 or quality > 100:
            _log_call("error", "VALIDATION_ERROR", "quality must be an integer 1..100")
            return _err("VALIDATION_ERROR", "quality must be an integer 1..100")
        if format != "jpeg":
            _log_call("error", "VALIDATION_ERROR", "quality is only allowed when format is jpeg")
            return _err("VALIDATION_ERROR", "quality is only allowed when format is jpeg")

    # ---- load session, authorize ambiently (no explicit credential param) ----
    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list): sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
    if not sess:
        _log_call("error", "NOT_FOUND", "sessionId not found")
        return _err("NOT_FOUND", "sessionId not found")

    # Expiration TTL (configured; default 10 min)
    settings = _load("settings.json")
    ttl_seconds = 600
    if isinstance(settings, dict):
        ttl_seconds = int(settings.get("browser_session_ttl_seconds", ttl_seconds) or ttl_seconds)

    def _parse_dt(x):
        if not isinstance(x, str): return None
        try:
            if x.endswith("Z"): x = x[:-1]
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    # auto-expire if needed
    last_seen = _parse_dt(sess.get("last_seen_at"))
    if sess.get("status") == "active" and last_seen:
        if (datetime.datetime.utcnow() - last_seen).total_seconds() > ttl_seconds:
            # transition active -> expired
            sess["status"] = "expired"
            sess["ended_at"] = now
            sess["updated_at"] = now
            for i, s in enumerate(sessions):
                if isinstance(s, dict) and s.get("id") == sessionId:
                    sessions[i] = sess
                    break
            _save("browser_sessions.json", sessions)

    if sess.get("status") != "active":
        _log_call("error", "INVALID_TRANSITION", "Cannot take screenshot on a non-active session", meta={"status": sess.get("status")})
        return _err("INVALID_TRANSITION", "Cannot take screenshot on a non-active session", status=sess.get("status"))

    # Must have an active page to capture (best-effort via current_url)
    page_url = sess.get("current_url")
    if page_url is None or not isinstance(page_url, str) or not page_url.strip():
        _log_call("error", "CONFLICT", "No active page is available to capture")
        return _err("CONFLICT", "No active page is available to capture")

    artifacts = _load("page_artifacts.json")
    if not isinstance(artifacts, list): artifacts = []

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex[:24]

    # ---- create capturing artifact ----
    art_id = _new_id("bt_art_")
    created_at = now
    capturing = {
        "id": art_id,
        "session_id": sessionId,
        "artifact_type": "screenshot",
        "status": "capturing",
        "page_url": page_url,
        "mime_type": "image/png" if format == "png" else "image/jpeg",
        "byte_size": None,
        "storage_backend": storageBackend,
        "storage_key": None,
        "inline_base64": None,
        "element_selector": None,
        "element_snapshot": None,
        "error_message": None,
        "captured_at": None,
        "created_at": created_at,
        "updated_at": created_at
    }
    artifacts.append(capturing)
    _save("page_artifacts.json", artifacts)

    # ---- attempt capture and transition to terminal state ----
    # Offline implementation: generate deterministic pseudo-image bytes based on session + url + time.
    try:
        seed = (sessionId + "|" + page_url + "|" + str(int(time.time())) + "|" + format + "|" + str(bool(fullPage))).encode("utf-8")
        digest = hashlib.sha256(seed).digest()
        # Create a small payload; real service would be full image bytes.
        payload_bytes = (digest * 64)[:4096]  # 4KB placeholder
        byte_size = len(payload_bytes)

        # Enforce basic constraints: byte_size >= 0
        if byte_size < 0:
            raise ValueError("Invalid byte_size")

        captured_at = now
        updated_at = now

        # Fill storage
        storage_key = None
        inline_b64 = None
        if storageBackend == "inline":
            inline_b64 = base64.b64encode(payload_bytes).decode("ascii")
        elif storageBackend == "local_fs":
            # write to local filesystem under /app/database/artifacts
            art_dir = os.path.join(_DB, "artifacts")
            os.makedirs(art_dir, exist_ok=True)
            ext = "png" if format == "png" else "jpg"
            storage_key = f"{sessionId}/{art_id}.{ext}"
            out_path = os.path.join(art_dir, storage_key.replace("/", "__"))
            with open(out_path, "wb") as f:
                f.write(payload_bytes)
        elif storageBackend == "s3":
            # store only a pointer (no external IO)
            ext = "png" if format == "png" else "jpg"
            storage_key = f"s3://browsertools-artifacts/{sessionId}/{art_id}.{ext}"

        # constraint: exactly one of(storage_key, inline_base64) when available and screenshot
        if (storage_key is None) == (inline_b64 is None):
            raise ValueError("Storage invariant violated")

        # Update artifact to available
        for i in range(len(artifacts)-1, -1, -1):
            a = artifacts[i]
            if isinstance(a, dict) and a.get("id") == art_id:
                a["status"] = "available"
                a["byte_size"] = byte_size
                a["storage_key"] = storage_key
                a["inline_base64"] = inline_b64
                a["captured_at"] = captured_at
                a["error_message"] = None
                a["updated_at"] = updated_at
                artifacts[i] = a
                break
        _save("page_artifacts.json", artifacts)

        # response: include inline_base64 only if requested and backend is inline
        resp_artifact = next((a for a in artifacts if isinstance(a, dict) and a.get("id") == art_id), None)
        if not resp_artifact:
            _log_call("error", "NOT_FOUND", "artifact not found after creation")
            return _err("NOT_FOUND", "artifact not found after creation")

        out = dict(resp_artifact)
        if storageBackend == "inline" and not includeBase64:
            out["inline_base64"] = None

        _log_call("ok", meta={"artifact_id": art_id, "storage_backend": storageBackend, "format": format})
        return {"artifact": out}

    except (OSError, ValueError) as e:
        # Transition capturing -> failed with error_message
        err_msg = str(e) or "capture failed"
        for i in range(len(artifacts)-1, -1, -1):
            a = artifacts[i]
            if isinstance(a, dict) and a.get("id") == art_id:
                a["status"] = "failed"
                a["error_message"] = err_msg
                a["captured_at"] = None
                a["storage_key"] = None
                a["inline_base64"] = None
                a["byte_size"] = None
                a["updated_at"] = now
                artifacts[i] = a
                break
        _save("page_artifacts.json", artifacts)
        _log_call("error", "CONFLICT", "Screenshot capture failed", meta={"detail": err_msg})
        return _err("CONFLICT", "Screenshot capture failed", detail=err_msg)

def wipeLogs(sessionId, source=None, **_extra):
    import json, os, datetime, re, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0025000" if __import__("os").path.isdir("./environment_mix/0025000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, code=None, message=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": "bt_req_" + uuid.uuid4().hex[:24],
            "service": "BrowserTools",
            "tool": "wipeLogs",
            "timestamp": now,
            "status": status,
            "latency_ms": latency_ms,
            "session_id": sessionId,
            "error_code": code,
            "error_message": message,
            "meta": meta or {}
        }
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list): reqs = []
        reqs.append(entry)
        _save("request_logs.json", reqs)

    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        _log_call("error", "VALIDATION_ERROR", "sessionId is invalid")
        return _err("VALIDATION_ERROR", "sessionId is invalid")
    if source is not None:
        if not isinstance(source, str) or source not in ("console", "network"):
            _log_call("error", "VALIDATION_ERROR", "source must be one of console|network")
            return _err("VALIDATION_ERROR", "source must be one of console|network")

    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list): sessions = []
    sess_idx = None
    sess = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            sess_idx = i
            break
    if not sess:
        _log_call("error", "NOT_FOUND", "sessionId not found")
        return _err("NOT_FOUND", "sessionId not found")

    # Session expiration: refuse mutating actions on expired/closed.
    # Auto-expire if TTL exceeded (configured; default 10 min).
    settings = _load("settings.json")
    ttl_seconds = 600
    if isinstance(settings, dict):
        try:
            ttl_seconds = int(settings.get("browser_session_ttl_seconds", ttl_seconds) or ttl_seconds)
        except Exception:
            ttl_seconds = 600

    def _parse_dt(x):
        if not isinstance(x, str): return None
        try:
            if x.endswith("Z"): x = x[:-1]
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    last_seen = _parse_dt(sess.get("last_seen_at"))
    if sess.get("status") == "active" and last_seen:
        if (datetime.datetime.utcnow() - last_seen).total_seconds() > ttl_seconds:
            sess["status"] = "expired"
            sess["ended_at"] = now
            sess["updated_at"] = now
            sessions[sess_idx] = sess
            _save("browser_sessions.json", sessions)

    if sess.get("status") != "active":
        _log_call("error", "INVALID_TRANSITION", "Cannot wipe logs on a non-active session", meta={"status": sess.get("status")})
        return _err("INVALID_TRANSITION", "Cannot wipe logs on a non-active session", status=sess.get("status"))

    logs = _load("browser_logs.json")
    if not isinstance(logs, list): logs = []

    before = len(logs)
    if source is None:
        remaining = [l for l in logs if not (isinstance(l, dict) and l.get("session_id") == sessionId)]
        wiped_count = before - len(remaining)
        wiped_sources = ["console", "network"]
    else:
        remaining = [l for l in logs if not (isinstance(l, dict) and l.get("session_id") == sessionId and l.get("source") == source)]
        wiped_count = before - len(remaining)
        wiped_sources = [source]

    if wiped_count == 0:
        # Still need to ensure "no success without effect" for mutation:
        # if session exists but there were no logs to wipe, treat as NOT_FOUND-equivalent for this operation.
        _log_call("error", "NOT_FOUND", "No logs matched the wipe criteria")
        return _err("NOT_FOUND", "No logs matched the wipe criteria")

    # Transactional semantics: save logs + reset buffer bytes
    _save("browser_logs.json", remaining)
    sess["log_buffer_bytes"] = 0
    sess["updated_at"] = now
    sessions[sess_idx] = sess
    _save("browser_sessions.json", sessions)

    _log_call("ok", meta={"wiped_count": wiped_count, "sources": wiped_sources})
    return {
        "session_id": sessionId,
        "wiped": {
            "sources": wiped_sources,
            "count": wiped_count
        },
        "log_buffer_bytes": sess["log_buffer_bytes"]
    }

