        if not isinstance(waitForIdleMs, int) or waitForIdleMs < 0 or waitForIdleMs > 120000:
            _log_call("error", "VALIDATION_ERROR", "waitForIdleMs must be an integer 0..120000")
            return _err("VALIDATION_ERROR", "waitForIdleMs must be an integer 0..120000")
    else:
        waitForIdleMs = 0

    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list): sessions = []
    sess_idx = None
    sess = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            sess_idx = i
            break
    if not sess:
        _log_call("error", "NOT_FOUND", "sessionId not found")
        return _err("NOT_FOUND", "sessionId not found")

    # Expire if TTL exceeded; refuse mutation on expired/closed
    settings = _load("settings.json")
    ttl_seconds = 600
    if isinstance(settings, dict):
        try:
            ttl_seconds = int(settings.get("browser_session_ttl_seconds", ttl_seconds) or ttl_seconds)
        except Exception:
            ttl_seconds = 600

    def _parse_dt(x):
        if not isinstance(x, str): return None
        try:
            if x.endswith("Z"): x = x[:-1]
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    last_seen = _parse_dt(sess.get("last_seen_at"))
    if sess.get("status") == "active" and last_seen:
        if (datetime.datetime.utcnow() - last_seen).total_seconds() > ttl_seconds:
            sess["status"] = "expired"
            sess["ended_at"] = now
            sess["updated_at"] = now
            sessions[sess_idx] = sess
            _save("browser_sessions.json", sessions)

    if sess.get("status") != "active":
        _log_call("error", "INVALID_TRANSITION", "Cannot run audit on a non-active session", meta={"status": sess.get("status")})
        return _err("INVALID_TRANSITION", "Cannot run audit on a non-active session", status=sess.get("status"))

    page_url = sess.get("current_url")
    if page_url is None or not isinstance(page_url, str) or not page_url.strip():
        _log_call("error", "CONFLICT", "No active page is available to audit")
        return _err("CONFLICT", "No active page is available to audit")

    audits = _load("audit_runs.json")
    if not isinstance(audits, list): audits = []

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex[:24]

    # Enqueue queued
    audit_id = _new_id("bt_aud_")
    queued = {
        "id": audit_id,
        "session_id": sessionId,
        "audit_type": "accessibility",
        "status": "queued",
        "page_url": page_url,
        "started_at": None,
        "finished_at": None,
        "score": None,
        "summary": None,
        "report": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    audits.append(queued)
    _save("audit_runs.json", audits)

    # Transition queued -> running -> terminal (simulate)
    # waitForIdleMs is simulated (do not actually sleep long; just record intent)
    started_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for i in range(len(audits)-1, -1, -1):
        a = audits[i]
        if isinstance(a, dict) and a.get("id") == audit_id:
            a["status"] = "running"
            a["started_at"] = started_at
            a["updated_at"] = started_at
            audits[i] = a
            break
    _save("audit_runs.json", audits)

    # Produce deterministic pseudo-report
    try:
        seed = (sessionId + "|" + page_url + "|accessibility|" + str(waitForIdleMs)).encode("utf-8")
        h = hashlib.sha256(seed).hexdigest()
        score = (int(h[:8], 16) % 101) / 100.0  # 0..1
        issues = int(h[8:12], 16) % 15
        summary = {
            "score": score,
            "issues_count": issues,
            "wait_for_idle_ms": waitForIdleMs,
            "generated_at": now
        }
        report = {
            "audit_type": "accessibility",
            "page_url": page_url,
            "score": score,
            "issues": [
                {"id": f"ax_{k}", "title": "Simulated issue", "severity": "warning" if k % 3 else "error"}
                for k in range(issues)
            ],
            "raw": {"seed": h}
        }

        finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        # success terminal
        for i in range(len(audits)-1, -1, -1):
            a = audits[i]
            if isinstance(a, dict) and a.get("id") == audit_id:
                a["status"] = "succeeded"
                a["finished_at"] = finished_at
                a["score"] = score
                a["summary"] = summary
                a["report"] = report
                a["error_message"] = None
                a["updated_at"] = finished_at
                audits[i] = a
                break
        _save("audit_runs.json", audits)

        out = next((a for a in audits if isinstance(a, dict) and a.get("id") == audit_id), None)
        if not out:
            _log_call("error", "NOT_FOUND", "audit run not found after execution")
            return _err("NOT_FOUND", "audit run not found after execution")

        _log_call("ok", meta={"audit_id": audit_id, "status": out.get("status")})
        return {"audit_run": out}

    except ValueError as e:
        finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for i in range(len(audits)-1, -1, -1):
            a = audits[i]
            if isinstance(a, dict) and a.get("id") == audit_id:
                a["status"] = "failed"
                a["finished_at"] = finished_at
                a["error_message"] = str(e) or "audit failed"
                a["updated_at"] = finished_at
                audits[i] = a
                break
        _save("audit_runs.json", audits)
        _log_call("error", "CONFLICT", "Audit failed", meta={"detail": str(e)})
        return _err("CONFLICT", "Audit failed", detail=str(e))

