        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _expire_if_needed(sess, sessions):
        # TTL: 5 minutes
        ttl_seconds = 300
        if sess.get("status") != "active":
