    # Ambient auth: no explicit credential parameters exist for this vendor tool.
    # If a session exists, caller is considered authorized in this local store model.

    expired_now = _expire_if_needed(sess, sessions)
    if expired_now:
        _save("browser_sessions.json", sessions)

    if sess.get("status") in ("closed", "expired"):
        _log_call("INVALID_TRANSITION", {"sessionId": sessionId, "status": sess.get("status")})
