        return _err("CONFLICT", "No active page is available to audit for this session.", sessionId=sessionId)

    audit_runs = _load("audit_runs.json")
    if not isinstance(audit_runs, list):
        audit_runs = []

    # Enqueue queued -> running -> terminal (succeeded)
    audit_id = _gen_id("bt_audit_")
