        "finished_at": None,
        "score": None,
        "summary": None,
        "report": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    audit_runs.append(row)

    # Transition to running
    started_at = now
    row["status"] = "running"
    row["started_at"] = started_at
    row["updated_at"] = now

    # Produce a deterministic-ish report (offline)
    # Basic performance "score" based on presence of title and viewport and user_agent (proxy for completeness).
    completeness = 0
    if sess.get("current_title"):
        completeness += 1
    if isinstance(sess.get("viewport"), dict) and sess["viewport"].get("width") and sess["viewport"].get("height"):
        completeness += 1
    if sess.get("user_agent"):
        completeness += 1
    score = min(1.0, max(0.0, 0.55 + 0.15 * completeness))

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    row["status"] = "succeeded"
    row["finished_at"] = finished_at
    row["score"] = float(score)
    row["summary"] = {
        "audit_type": "performance",
        "page_url": page_url,
        "score": row["score"],
        "generated_at": finished_at,
        "notes": [
            "Offline audit: score is heuristic and based on session metadata completeness."
        ]
    }
    row["report"] = {
        "id": audit_id,
        "type": "lighthouse.performance",
        "page_url": page_url,
        "timing": {"started_at": started_at, "finished_at": finished_at},
        "metrics": {
            "score": row["score"],
            "metadata_completeness": completeness
        }
    }
    row["updated_at"] = finished_at

    # Persist
    _save("audit_runs.json", audit_runs)

    _log_call("OK", {"sessionId": sessionId, "auditId": audit_id})
    return {"audit_run": row}

