                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status_code, meta=None):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        reqs.append({
            "id": "req_" + uuid.uuid4().hex,
            "service": "BrowserTools",
            "endpoint": "runDebuggerMode",
            "status": status_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", reqs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _expire_if_needed(sess, sessions):
        ttl_seconds = 300
        if sess.get("status") != "active":
            return False
        last_seen = _parse_dt(sess.get("last_seen_at"))
        if not last_seen:
            return False
        if (datetime.datetime.utcnow() - last_seen).total_seconds() > ttl_seconds:
            sess["status"] = "expired"
            sess["ended_at"] = now
            sess["updated_at"] = now
            for i, s in enumerate(sessions):
                if s.get("id") == sess.get("id"):
                    sessions[i] = sess
                    break
            return True
        return False

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:24]

    def _allowed_transition(frm, to):
        transitions = {
            "requested": ["enabled", "failed", "disabled"],
            "enabled": ["disabled", "failed"],
            "disabled": ["requested"],
            "failed": ["requested", "disabled"]
        }
        return to in transitions.get(frm, [])

    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        _log_call("VALIDATION_ERROR", {"field": "sessionId"})
        return _err("VALIDATION_ERROR", "sessionId is missing or invalid.", field="sessionId")

    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if s.get("id") == sessionId), None)
    if not sess:
        _log_call("NOT_FOUND", {"sessionId": sessionId})
        return _err("NOT_FOUND", "Browser session not found.", sessionId=sessionId)

    expired_now = _expire_if_needed(sess, sessions)
    if expired_now:
        _save("browser_sessions.json", sessions)

    if sess.get("status") in ("closed", "expired"):
        _log_call("CONFLICT", {"sessionId": sessionId, "status": sess.get("status")})
        return _err("CONFLICT", "Session is not in a state that can enter Debugger Mode.", sessionId=sessionId, status=sess.get("status"))

    modes = _load("session_modes.json")
    if not isinstance(modes, list):
        modes = []

    # Ensure uniqueness: only one enabled debugger per session.
    enabled = [m for m in modes if m.get("session_id") == sessionId and m.get("mode_type") == "debugger" and m.get("status") == "enabled"]
    if enabled:
        # Idempotent: already enabled; return the existing enabled row (latest updated_at)
        enabled.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        out = enabled[0]
        _log_call("OK", {"sessionId": sessionId, "modeId": out.get("id"), "idempotent": True})
        return {"session": sess, "mode": out}

    # Find most recent debugger mode row for session; else create new requested
    dbg_rows = [m for m in modes if m.get("session_id") == sessionId and m.get("mode_type") == "debugger"]
    dbg_rows.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
    row = dbg_rows[0] if dbg_rows else None

    if row is None:
        row = {
            "id": _gen_id("bt_mode_"),
            "session_id": sessionId,
            "mode_type": "debugger",
            "status": "requested",
            "details": None,
            "error_message": None,
            "requested_at": now,
            "effective_at": None,
            "created_at": now,
            "updated_at": now
        }
        modes.append(row)
    else:
        # If last state prevents enabling, attempt legal transition via requested
        cur = row.get("status")
        if cur not in ("requested", "disabled", "failed", "enabled"):
            _log_call("INVALID_TRANSITION", {"sessionId": sessionId, "modeStatus": cur})
            return _err("INVALID_TRANSITION", "Mode is in an unknown state and cannot be enabled.", sessionId=sessionId, status=cur)
        if cur != "requested":
            if _allowed_transition(cur, "requested"):
                row["status"] = "requested"
                row["requested_at"] = now
                row["effective_at"] = None
                row["error_message"] = None
                row["updated_at"] = now
            elif cur == "enabled":
                # would have been caught above
                pass
            else:
                _log_call("INVALID_TRANSITION", {"sessionId": sessionId, "from": cur, "to": "requested"})
                return _err("INVALID_TRANSITION", "Cannot request debugger mode from current state.", sessionId=sessionId, from_status=cur, to_status="requested")

    # Transition requested -> enabled
    if row.get("status") != "requested":
        _log_call("INVALID_TRANSITION", {"sessionId": sessionId, "status": row.get("status")})
        return _err("INVALID_TRANSITION", "Debugger mode cannot be enabled from current state.", sessionId=sessionId, status=row.get("status"))
    if not _allowed_transition("requested", "enabled"):
        _log_call("INVALID_TRANSITION", {"sessionId": sessionId})
        return _err("INVALID_TRANSITION", "Debugger mode cannot be enabled.", sessionId=sessionId)

    row["status"] = "enabled"
    row["effective_at"] = now
    row["updated_at"] = now

    # Persist updated modes list (row mutated in-place)
    _save("session_modes.json", modes)

    _log_call("OK", {"sessionId": sessionId, "modeId": row.get("id")})
    return {"session": sess, "mode": row}

def runAuditMode(sessionId, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0025000" if __import__("os").path.isdir("./environment_mix/0025000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _REQLOG_FILE = "request_logs.json"  # best-effort; may not exist in schema
    _SESSION_FILE = "browser_sessions.json"
    _MODE_FILE = "session_modes.json"
    _AUDIT_FILE = "audit_runs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_to_iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _log_request(status, error_code=None):
        logs = _load(_REQLOG_FILE)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "bt_req_" + hashlib.sha1(f"{time.time_ns()}:{sessionId}:runAuditMode".encode("utf-8")).hexdigest()[:16],
            "endpoint": "runAuditMode",
            "session_id": sessionId,
            "status": status,
            "error_code": error_code,
            "timestamp": _now(),
        }
        logs.append(row)
        try:
            _save(_REQLOG_FILE, logs)
        except Exception:
            pass

    def _expire_if_needed(sess):
        # TTL: 60 seconds default
        ttl_seconds = 60
        last = _parse_dt(sess.get("last_seen_at"))
        if sess.get("status") == "active" and last is not None:
            age = (datetime.datetime.utcnow() - last).total_seconds()
            if age > ttl_seconds:
                # transition active -> expired
                sess["status"] = "expired"
                sess["ended_at"] = _now()
                sess["updated_at"] = _now()
        return sess

    # Validate
    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sessionId is required and must match ^bt_sess_[A-Za-z0-9]+$")

    sessions = _load(_SESSION_FILE)
    if not isinstance(sessions, list):
        _log_request("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unable to access sessions store")

    sess = next((s for s in sessions if s.get("id") == sessionId), None)
    if not sess:
        _log_request("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Browser session not found", sessionId=sessionId)

    # Expire check
    before_status = sess.get("status")
    sess = _expire_if_needed(sess)
    if sess.get("status") != before_status:
        for i, s in enumerate(sessions):
            if s.get("id") == sessionId:
                sessions[i] = sess
                break
        _save(_SESSION_FILE, sessions)

    if sess.get("status") in ("expired", "closed"):
        _log_request("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot enable audit mode on a closed/expired session", status=sess.get("status"))

    # Load modes
    modes = _load(_MODE_FILE)
    if not isinstance(modes, list):
        modes = []

    now = _now()

    # Find existing enabled audit mode for session (idempotent)
    enabled = None
    for m in modes:
        if m.get("session_id") == sessionId and m.get("mode_type") == "audit" and m.get("status") == "enabled":
            enabled = m
            break

    if enabled:
        # Already enabled: return current state
        _log_request("ok")
        return {
            "session": sess,
            "mode": enabled,
        }

    # Otherwise, create a requested row then transition to enabled (requested -> enabled is allowed)
    new_id = "bt_mode_" + hashlib.sha1(f"{time.time_ns()}:{sessionId}:audit".encode("utf-8")).hexdigest()[:16]
    requested_row = {
        "id": new_id,
        "session_id": sessionId,
        "mode_type": "audit",
        "status": "requested",
        "details": None,
        "error_message": None,
        "requested_at": now,
        "effective_at": None,
        "created_at": now,
        "updated_at": now,
    }
    modes.append(requested_row)

    # Transition requested -> enabled
    requested_row["status"] = "enabled"
    requested_row["effective_at"] = now
    requested_row["updated_at"] = now

    _save(_MODE_FILE, modes)

    # May enqueue audits (dedupe within short window by queued/running, and same session/audit_type/page_url)
    # Use current_url as page_url if present.
    page_url = sess.get("current_url")
    enqueued = []
    if isinstance(page_url, str) and page_url.strip():
        audits = _load(_AUDIT_FILE)
        if not isinstance(audits, list):
            audits = []

        audit_types = ["accessibility", "performance", "seo", "best_practices"]
        dedupe_window_seconds = 120
        now_dt = datetime.datetime.utcnow()

        def _is_dup(a):
            if a.get("session_id") != sessionId:
                return False
            if a.get("audit_type") not in audit_types:
                return False
            if a.get("page_url") != page_url:
                return False
            if a.get("status") not in ("queued", "running"):
                return False
            cdt = _parse_dt(a.get("created_at"))
            if cdt is None:
                return True  # treat malformed timestamps as dup to be safe
            return (now_dt - cdt).total_seconds() <= dedupe_window_seconds

        existing_dups = {(a.get("audit_type")): a for a in audits if _is_dup(a)}

        changed = False
        for at in audit_types:
            if at in existing_dups:
                enqueued.append(existing_dups[at])
                continue
            aid = "bt_audit_" + hashlib.sha1(f"{time.time_ns()}:{sessionId}:{at}:{page_url}".encode("utf-8")).hexdigest()[:16]
            row = {
                "id": aid,
                "session_id": sessionId,
                "audit_type": at,
                "status": "queued",
                "page_url": page_url,
                "started_at": None,
                "finished_at": None,
                "score": None,
                "summary": None,
                "report": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now,
            }
            audits.append(row)
            enqueued.append(row)
            changed = True

        if changed:
            _save(_AUDIT_FILE, audits)

    _log_request("ok")
    return {
        "session": sess,
        "mode": requested_row,
        "enqueued_audits": enqueued,
    }

def runBestPracticesAudit(sessionId, **_extra):
    import json, os, datetime, re, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0025000" if __import__("os").path.isdir("./environment_mix/0025000") else "/app/database")
    def _load(n):
