        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _REQLOG_FILE = "request_logs.json"
    _SESSION_FILE = "browser_sessions.json"
    _AUDIT_FILE = "audit_runs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(status, error_code=None):
        logs = _load(_REQLOG_FILE)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "bt_req_" + hashlib.sha1(f"{time.time_ns()}:{sessionId}:runBestPracticesAudit".encode("utf-8")).hexdigest()[:16],
            "endpoint": "runBestPracticesAudit",
            "session_id": sessionId,
            "status": status,
            "error_code": error_code,
            "timestamp": _now(),
        }
        logs.append(row)
        try:
            _save(_REQLOG_FILE, logs)
        except Exception:
            pass

    def _expire_if_needed(sess):
        ttl_seconds = 60
        last = _parse_dt(sess.get("last_seen_at"))
        if sess.get("status") == "active" and last is not None:
            age = (datetime.datetime.utcnow() - last).total_seconds()
            if age > ttl_seconds:
                sess["status"] = "expired"
                sess["ended_at"] = _now()
                sess["updated_at"] = _now()
        return sess

    # Validate
    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sessionId is required and must match ^bt_sess_[A-Za-z0-9]+$")

    sessions = _load(_SESSION_FILE)
    if not isinstance(sessions, list):
        _log_request("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unable to access sessions store")

    sess = next((s for s in sessions if s.get("id") == sessionId), None)
    if not sess:
        _log_request("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Browser session not found", sessionId=sessionId)

    # Expire if needed and persist
    before_status = sess.get("status")
    sess = _expire_if_needed(sess)
    if sess.get("status") != before_status:
        for i, s in enumerate(sessions):
            if s.get("id") == sessionId:
                sessions[i] = sess
                break
        _save(_SESSION_FILE, sessions)

    if sess.get("status") in ("expired", "closed"):
        _log_request("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot run audit on a closed/expired session", status=sess.get("status"))

    page_url = sess.get("current_url")
    if not isinstance(page_url, str) or not page_url.strip():
        _log_request("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Session has no active page to audit", sessionId=sessionId)

    audits = _load(_AUDIT_FILE)
    if not isinstance(audits, list):
        audits = []

    now = _now()
    now_dt = datetime.datetime.utcnow()
    dedupe_window_seconds = 120

    def _is_dup(a):
        if a.get("session_id") != sessionId:
            return False
        if a.get("audit_type") != "best_practices":
            return False
        if a.get("page_url") != page_url:
            return False
        if a.get("status") not in ("queued", "running"):
            return False
        cdt = _parse_dt(a.get("created_at"))
        if cdt is None:
            return True
        return (now_dt - cdt).total_seconds() <= dedupe_window_seconds

    dup = next((a for a in audits if _is_dup(a)), None)
    if dup:
        _log_request("ok")
        return {"audit": dup}

    # Enqueue queued
    aid = "bt_audit_" + hashlib.sha1(f"{time.time_ns()}:{sessionId}:best_practices:{page_url}".encode("utf-8")).hexdigest()[:16]
    audit = {
        "id": aid,
        "session_id": sessionId,
        "audit_type": "best_practices",
        "status": "queued",
        "page_url": page_url,
        "started_at": None,
        "finished_at": None,
        "score": None,
        "summary": None,
        "report": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    audits.append(audit)

    # Transition queued -> running -> terminal
    # We "execute" synchronously and persist the final report/summary.
    started = _now()
    audit["status"] = "running"
    audit["started_at"] = started
    audit["updated_at"] = started

    # Generate a deterministic-ish score based on page_url to keep stable across runs
    h = int(hashlib.sha1(page_url.encode("utf-8")).hexdigest()[:8], 16)
    rng = random.Random(h)
    score = max(0.0, min(1.0, 0.6 + rng.random() * 0.4))

    finished = _now()
    audit["status"] = "succeeded"
    audit["finished_at"] = finished
    audit["score"] = float(f"{score:.3f}")
    audit["summary"] = {
        "audit_type": "best_practices",
        "page_url": page_url,
        "score": audit["score"],
        "top_issues": [
            {"id": "uses-https", "severity": "info"},
            {"id": "no-console-errors", "severity": "warning"},
        ],
    }
    audit["report"] = {
        "lighthouse_version": "local-offline-1.0",
        "requested_url": page_url,
        "final_url": page_url,
        "categories": {
            "best-practices": {
                "score": audit["score"],
            }
        },
        "generated_at": finished,
    }
    audit["error_message"] = None
    audit["updated_at"] = finished

    _save(_AUDIT_FILE, audits)
    _log_request("ok")
    return {"audit": audit}

