    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s, field_name="datetime"):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 date-time string")
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]), None
            return datetime.datetime.fromisoformat(s), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 date-time string")

    def _log_request(status_txt, error_code=None):
        logs = _load(_REQLOG_FILE)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "bt_req_" + hashlib.sha1(f"{time.time_ns()}:listBrowserSessions".encode("utf-8")).hexdigest()[:16],
            "endpoint": "listBrowserSessions",
            "status": status_txt,
            "error_code": error_code,
            "timestamp": _now(),
        }
        logs.append(row)
        try:
            _save(_REQLOG_FILE, logs)
        except Exception:
            pass

    def _decode_cursor(c):
        if c is None:
            return None, None
        if not isinstance(c, str) or not c:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            return obj, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if status is not None and status not in ("active", "closed", "expired"):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, closed, expired")

    if sort is None:
        sort = "-started_at"
    if sort not in ("started_at", "-started_at", "last_seen_at", "-last_seen_at"):
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort must be one of: started_at, -started_at, last_seen_at, -last_seen_at")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")

    since_dt, err = _parse_dt(since, "since")
    if err:
        _log_request("error", "VALIDATION_ERROR")
        return err
    until_dt, err = _parse_dt(until, "until")
    if err:
        _log_request("error", "VALIDATION_ERROR")
        return err
    if since_dt and until_dt and since_dt > until_dt:
        _log_request("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "since must be <= until")

    cur, err = _decode_cursor(cursor)
    if err:
        _log_request("error", "VALIDATION_ERROR")
        return err

    sessions = _load(_SESSION_FILE)
    if not isinstance(sessions, list):
        _log_request("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unable to access sessions store")

    # Filtering
    def _parse_dt_loose(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    rows = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        st = _parse_dt_loose(s.get("started_at"))
        if since_dt and (st is None or st < since_dt):
            continue
        if until_dt and (st is None or st > until_dt):
            continue
        rows.append(s)

    # Sorting
    field = sort.lstrip("-")
    desc = sort.startswith("-")

    def _key(r):
        dt = _parse_dt_loose(r.get(field))
        # None sorts last consistently
        return (dt is None, dt if dt is not None else datetime.datetime.min, r.get("id") or "")

    rows.sort(key=_key, reverse=desc)

    # Cursor paging (opaque but we store last seen key)
    start_index = 0
    if cur is not None:
        if cur.get("sort") != sort:
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor sort mismatch")
        last_id = cur.get("last_id")
        last_val = cur.get("last_val")
        if not isinstance(last_id, str) or not isinstance(last_val, str):
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")
        # find first item after (last_val,last_id) in current sort order
        # compare by parsed datetime then id, respecting nulls
        last_dt = _parse_dt_loose(last_val)
        def _cmp_tuple(r):
            dt = _parse_dt_loose(r.get(field))
            return (dt is None, dt if dt is not None else datetime.datetime.min, r.get("id") or "")
        target = (last_dt is None, last_dt if last_dt is not None else datetime.datetime.min, last_id)
        for i, r in enumerate(rows):
            if _cmp_tuple(r) == target:
                start_index = i + 1
                break
        else:
            # If cursor not found in filtered set, treat as invalid
            _log_request("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid or out of range")

    page = rows[start_index:start_index + limit]
    has_more = start_index + limit < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({
            "sort": sort,
            "last_id": last.get("id"),
            "last_val": last.get(field),
        })

    _log_request("ok")
    return {
        "sessions": page,
        "total": len(rows),
        "has_more": bool(has_more),
        "next_cursor": next_cursor,
        "limit": limit,
        "sort": sort,
    }

def createBrowserSession(userAgent=None, viewport=None, currentUrl=None, currentTitle=None, logBufferLimitBytes=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0025000" if __import__("os").path.isdir("./environment_mix/0025000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    # No explicit credential parameter; ambient auth: allow if service is callable.
    # (If in the future an auth datastore exists, resolve a working combination here.)

    # Validate inputs
    if userAgent is not None and not isinstance(userAgent, str):
        return _err("VALIDATION_ERROR", "userAgent must be a string")
    if currentUrl is not None and not isinstance(currentUrl, str):
        return _err("VALIDATION_ERROR", "currentUrl must be a string")
    if currentTitle is not None and not isinstance(currentTitle, str):
        return _err("VALIDATION_ERROR", "currentTitle must be a string")
    if logBufferLimitBytes is not None:
        if not isinstance(logBufferLimitBytes, int):
            return _err("VALIDATION_ERROR", "logBufferLimitBytes must be an integer")
        if logBufferLimitBytes < 1024:
            return _err("VALIDATION_ERROR", "logBufferLimitBytes must be >= 1024")
    if viewport is not None:
        if not isinstance(viewport, dict):
            return _err("VALIDATION_ERROR", "viewport must be an object")
        allowed = {"width", "height", "deviceScaleFactor", "isMobile"}
        extra_keys = set(viewport.keys()) - allowed
        if extra_keys:
            return _err("VALIDATION_ERROR", "viewport contains unknown fields", fields=sorted(list(extra_keys)))
        if "width" not in viewport or "height" not in viewport:
            return _err("VALIDATION_ERROR", "viewport.width and viewport.height are required")
        if not isinstance(viewport.get("width"), int) or viewport["width"] < 0:
            return _err("VALIDATION_ERROR", "viewport.width must be a non-negative integer")
        if not isinstance(viewport.get("height"), int) or viewport["height"] < 0:
            return _err("VALIDATION_ERROR", "viewport.height must be a non-negative integer")
        if "deviceScaleFactor" in viewport and viewport["deviceScaleFactor"] is not None:
            if not isinstance(viewport["deviceScaleFactor"], (int, float)) or viewport["deviceScaleFactor"] < 0:
                return _err("VALIDATION_ERROR", "viewport.deviceScaleFactor must be a non-negative number")
        if "isMobile" in viewport and viewport["isMobile"] is not None:
            if not isinstance(viewport["isMobile"], bool):
                return _err("VALIDATION_ERROR", "viewport.isMobile must be a boolean")

    sessions = _load("browser_sessions.json")

    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    sess_id = "bt_sess_" + uuid.uuid4().hex[:24]

    # Enforce schema constraint: log_buffer_limit_bytes >= 1048576
    # Tool allows minimum 1024, but backend schema requires >= 1MiB; use max(default, 1MiB).
    limit = logBufferLimitBytes if logBufferLimitBytes is not None else 1048576
    if limit < 1048576:
        limit = 1048576

    row = {
        "id": sess_id,
        "status": "active",
        "started_at": now,
        "ended_at": None,
        "current_url": currentUrl if currentUrl is not None else None,
        "current_title": currentTitle if currentTitle is not None else None,
        "user_agent": userAgent if userAgent is not None else None,
        "viewport": viewport if viewport is not None else None,
        "last_seen_at": now,
        "log_buffer_bytes": 0,
        "log_buffer_limit_bytes": int(limit),
        "created_at": now,
        "updated_at": now
    }

    sessions.append(row)
    _save("browser_sessions.json", sessions)

    latency_ms = int((time.time() - start) * 1000)
    return {
        "session": row,
        "meta": {"latency_ms": latency_ms}
    }

def updateBrowserSession(sessionId, status=None, currentUrl=None, currentTitle=None, lastSeenAt=None, viewport=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0025000" if __import__("os").path.isdir("./environment_mix/0025000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    # Validate inputs
    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        return _err("VALIDATION_ERROR", "sessionId is invalid")

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "closed", "expired"):
            return _err("VALIDATION_ERROR", "status must be one of: active, closed, expired")

    if currentUrl is not None and not isinstance(currentUrl, str):
        return _err("VALIDATION_ERROR", "currentUrl must be a string")
    if currentTitle is not None and not isinstance(currentTitle, str):
        return _err("VALIDATION_ERROR", "currentTitle must be a string")

    parsed_last_seen = None
    if lastSeenAt is not None:
        if not isinstance(lastSeenAt, str):
            return _err("VALIDATION_ERROR", "lastSeenAt must be an RFC3339 date-time string")
        try:
            s = lastSeenAt.replace("Z", "+00:00")
            parsed_last_seen = datetime.datetime.fromisoformat(s)
            if parsed_last_seen.tzinfo is None:
                parsed_last_seen = parsed_last_seen.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return _err("VALIDATION_ERROR", "lastSeenAt must be an RFC3339 date-time string")

    if viewport is not None:
        if not isinstance(viewport, dict):
            return _err("VALIDATION_ERROR", "viewport must be an object")
        allowed = {"width", "height", "deviceScaleFactor", "isMobile"}
        extra_keys = set(viewport.keys()) - allowed
        if extra_keys:
            return _err("VALIDATION_ERROR", "viewport contains unknown fields", fields=sorted(list(extra_keys)))
        if "width" in viewport and viewport["width"] is not None:
            if not isinstance(viewport["width"], int) or viewport["width"] < 0:
                return _err("VALIDATION_ERROR", "viewport.width must be an integer >= 0")
        if "height" in viewport and viewport["height"] is not None:
            if not isinstance(viewport["height"], int) or viewport["height"] < 0:
                return _err("VALIDATION_ERROR", "viewport.height must be an integer >= 0")
        if "deviceScaleFactor" in viewport and viewport["deviceScaleFactor"] is not None:
            if not isinstance(viewport["deviceScaleFactor"], (int, float)) or viewport["deviceScaleFactor"] < 0:
                return _err("VALIDATION_ERROR", "viewport.deviceScaleFactor must be a number >= 0")
        if "isMobile" in viewport and viewport["isMobile"] is not None:
            if not isinstance(viewport["isMobile"], bool):
                return _err("VALIDATION_ERROR", "viewport.isMobile must be a boolean")

    # Load and find session
    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess_idx = None
    session = None
    for i, r in enumerate(sessions):
        if isinstance(r, dict) and r.get("id") == sessionId:
            sess_idx = i
            session = r
            break
    if session is None:
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    # Apply updates with lifecycle enforcement
    changed = False

    # Status transition rules:
    # - Only transitions from active -> closed|expired are permitted.
    # - Refuse modifications to closed/expired sessions except where explicitly allowed by transition rules
    #   (i.e., no transitions out of closed/expired).
    current_status = session.get("status")
    if current_status not in ("active", "closed", "expired"):
        return _err("CONFLICT", "Session has invalid stored status", status=current_status)

    # If non-status fields are being updated, require session to be active
    non_status_updates = any(v is not None for v in (currentUrl, currentTitle, lastSeenAt, viewport))
    if non_status_updates and current_status != "active":
        return _err("INVALID_TRANSITION", f"Cannot modify fields on a {current_status} session")

    if status is not None and status != current_status:
        transitions = {"active": {"closed", "expired"}, "closed": set(), "expired": set()}
        if status not in transitions.get(current_status, set()):
            return _err("INVALID_TRANSITION", f"Illegal status transition: {current_status} -> {status}")
        session["status"] = status
        changed = True
        # ended_at constraints
        if status in ("closed", "expired"):
            session["ended_at"] = _iso(now)
        else:
            session["ended_at"] = None

    # ended_at constraint for active
    if session.get("status") == "active":
        if session.get("ended_at") is not None:
            session["ended_at"] = None
            changed = True
    else:
        if session.get("ended_at") is None:
            session["ended_at"] = _iso(now)
            changed = True

    if currentUrl is not None:
        session["current_url"] = currentUrl
        changed = True
    if currentTitle is not None:
        session["current_title"] = currentTitle
        changed = True
    if parsed_last_seen is not None:
        session["last_seen_at"] = _iso(parsed_last_seen)
        changed = True
    if viewport is not None:
        # store as-is but normalize keys to schema's expected shape if possible
        # schema says viewport has width,height,device_scale_factor; but tool uses deviceScaleFactor/isMobile too.
        vp = dict(session.get("viewport") or {})
        if "width" in viewport:
            vp["width"] = viewport.get("width")
        if "height" in viewport:
            vp["height"] = viewport.get("height")
        if "deviceScaleFactor" in viewport:
            vp["device_scale_factor"] = viewport.get("deviceScaleFactor")
        if "isMobile" in viewport:
            vp["is_mobile"] = viewport.get("isMobile")
        session["viewport"] = vp
        changed = True

    # Validate numeric constraints if present
    lbb = session.get("log_buffer_bytes")
    lbl = session.get("log_buffer_limit_bytes")
    if not isinstance(lbb, int) or lbb < 0:
        return _err("CONFLICT", "Session has invalid stored log_buffer_bytes")
    if not isinstance(lbl, int) or lbl < 1048576:
        return _err("CONFLICT", "Session has invalid stored log_buffer_limit_bytes")
    if lbb > lbl:
        return _err("CONFLICT", "Session violates log buffer constraints", log_buffer_bytes=lbb, log_buffer_limit_bytes=lbl)

    if not changed:
        # No success without effect
        return _err("VALIDATION_ERROR", "No updatable fields provided or values identical; no changes applied")

    session["updated_at"] = _iso(now)
    sessions[sess_idx] = session
    _save("browser_sessions.json", sessions)

    return {
        "session": session,
        "meta": {
            "latency_ms": int((time.time() - start) * 1000)
        }
    }

def createBrowserLogs(sessionId, entries, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0025000" if __import__("os").path.isdir("./environment_mix/0025000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    if not isinstance(sessionId, str) or not re.match(r"^bt_sess_[A-Za-z0-9]+$", sessionId):
        return _err("VALIDATION_ERROR", "sessionId is invalid")
    if not isinstance(entries, list):
        return _err("VALIDATION_ERROR", "entries must be an array")
    if len(entries) < 1 or len(entries) > 1000:
        return _err("VALIDATION_ERROR", "entries must have between 1 and 1000 items")

    allowed_sources = {"console", "network"}
    allowed_levels = {"debug", "info", "warning", "error"}
    canonical_event_types = {"console.message", "console.exception", "network.request", "network.response", "network.failure"}

    # Accept some common aliases seen in telemetry; normalize to canonical values.
    # (Audit defect shows "log" arriving; treat as console.message)
    event_type_aliases = {
        "log": "console.message",
        "console.log": "console.message",
        "console.error": "console.message",
        "console.warn": "console.message",
        "console.info": "console.message",
        "exception": "console.exception",
    }

    def _parse_dt(s, field_path):
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_path} must be an RFC3339 date-time string")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field_path} must be an RFC3339 date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0), None

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    # Load session and enforce lifecycle for ingest
    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = None
    sess_idx = None
    for i, r in enumerate(sessions):
        if isinstance(r, dict) and r.get("id") == sessionId:
            sess = r
            sess_idx = i
            break
    if sess is None:
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    if sess.get("status") in ("closed", "expired"):
        return _err("INVALID_TRANSITION", f"Cannot ingest logs into a {sess.get('status')} session")

    # Validate entries and build rows (but do not persist until quota/evictions calculated)
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    new_rows = []
    approx_new_bytes = 0

    allowed_keys = {"source", "level", "eventType", "message", "timestamp", "url", "httpMethod", "httpStatus", "requestId", "initiator", "durationMs", "payload"}
    for idx, e in enumerate(entries):
        if not isinstance(e, dict):
            return _err("VALIDATION_ERROR", f"entries[{idx}] must be an object")
        extra_keys = set(e.keys()) - allowed_keys
        if extra_keys:
            return _err("VALIDATION_ERROR", f"entries[{idx}] contains unknown fields", fields=sorted(list(extra_keys)))
        for req in ("source", "level", "eventType", "timestamp"):
            if req not in e:
                return _err("VALIDATION_ERROR", f"entries[{idx}].{req} is required")

        source = e.get("source")
        level = e.get("level")
        eventType = e.get("eventType")
        ts_raw = e.get("timestamp")

        if not isinstance(source, str) or source not in allowed_sources:
            return _err("VALIDATION_ERROR", f"entries[{idx}].source must be one of: console, network")
        if not isinstance(level, str) or level not in allowed_levels:
            return _err("VALIDATION_ERROR", f"entries[{idx}].level must be one of: debug, info, warning, error")
        if not isinstance(eventType, str) or not eventType.strip():
            return _err("VALIDATION_ERROR", f"entries[{idx}].eventType must be a non-empty string")

        normalized_event_type = event_type_aliases.get(eventType, eventType)
        if normalized_event_type not in canonical_event_types:
            return _err(
                "VALIDATION_ERROR",
                f"entries[{idx}].eventType is not recognized; must be a known event type or alias",
                allowed_event_types=sorted(list(canonical_event_types)),
                received=eventType
            )

        ts, err = _parse_dt(ts_raw, f"entries[{idx}].timestamp")
        if err:
            return err

        http_status = e.get("httpStatus")
        if http_status is not None:
            if not isinstance(http_status, int):
                return _err("VALIDATION_ERROR", f"entries[{idx}].httpStatus must be an integer")
            # Business/schema constraint: 100..599 when not null
            if http_status < 100 or http_status > 599:
                return _err("VALIDATION_ERROR", f"entries[{idx}].httpStatus must be between 100 and 599")

        duration_ms = e.get("durationMs")
        if duration_ms is not None:
            if not isinstance(duration_ms, int):
                return _err("VALIDATION_ERROR", f"entries[{idx}].durationMs must be an integer")
            if duration_ms < 0:
                return _err("VALIDATION_ERROR", f"entries[{idx}].durationMs must be >= 0")

        # Build row in collection schema (snake_case)
        row = {
            "id": "bt_log_" + secrets.token_hex(12),
            "session_id": sessionId,
            "source": source,
            "level": level,
            "event_type": normalized_event_type,
            "message": e.get("message") if isinstance(e.get("message"), str) else (None if e.get("message") is None else str(e.get("message"))),
            "timestamp": _iso(ts),
            "url": e.get("url") if e.get("url") is None or isinstance(e.get("url"), str) else str(e.get("url")),
            "http_method": e.get("httpMethod") if e.get("httpMethod") is None or isinstance(e.get("httpMethod"), str) else str(e.get("httpMethod")),
            "http_status": http_status,
            "request_id": e.get("requestId") if e.get("requestId") is None or isinstance(e.get("requestId"), str) else str(e.get("requestId")),
            "initiator": e.get("initiator") if e.get("initiator") is None or isinstance(e.get("initiator"), str) else str(e.get("initiator")),
            "duration_ms": float(duration_ms) if duration_ms is not None else None,
            "payload": e.get("payload") if isinstance(e.get("payload"), dict) or e.get("payload") is None else {"value": e.get("payload")},
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        # Approx byte sizing for buffer accounting
        approx_new_bytes += len(json.dumps(row, ensure_ascii=False))
        new_rows.append(row)

    # Load existing logs
    logs = _load("browser_logs.json")
    if not isinstance(logs, list):
        logs = []

    # Enforce quota: evict oldest logs for this session if needed to fit new bytes
    # If even after evicting all session logs it doesn't fit, reject.
    limit = sess.get("log_buffer_limit_bytes")
    used = sess.get("log_buffer_bytes")
    if not isinstance(limit, int) or limit < 1048576:
        return _err("CONFLICT", "Session has invalid stored log_buffer_limit_bytes")
    if not isinstance(used, int) or used < 0:
        return _err("CONFLICT", "Session has invalid stored log_buffer_bytes")

    session_log_idxs = [i for i, r in enumerate(logs) if isinstance(r, dict) and r.get("session_id") == sessionId]
    session_logs = [logs[i] for i in session_log_idxs]

    def _log_size(r):
        try:
            return len(json.dumps(r, ensure_ascii=False))
        except Exception:
            return 0

    # Sort session logs by timestamp asc, created_at asc as tiebreaker for eviction order
    def _parse_sort_dt(v):
        if not isinstance(v, str):
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        try:
            dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    session_logs_sorted = sorted(
        session_logs,
        key=lambda r: (_parse_sort_dt(r.get("timestamp")), _parse_sort_dt(r.get("created_at")))
    )

    evicted = 0
    freed = 0
    # ensure used does not exceed limit already: if it does, evict until it doesn't
    # and also evict for the incoming batch
    while (used - freed + approx_new_bytes) > limit and session_logs_sorted:
        victim = session_logs_sorted.pop(0)
        freed += _log_size(victim)
        evicted += 1

    if (used - freed + approx_new_bytes) > limit and not session_logs_sorted:
        # would require rejecting; cannot fit even after deleting all session logs
        return _err("QUOTA_EXCEEDED", "Log buffer limit exceeded; batch too large to fit in session buffer", log_buffer_limit_bytes=limit)

    # Apply evictions to logs array (hard delete) preserving other sessions
    if evicted:
        victim_ids = set()
        # victims are those removed from the front; reconstruct by taking remaining ids
        remaining_ids = set(r.get("id") for r in session_logs_sorted if isinstance(r, dict))
        for r in session_logs:
            if isinstance(r, dict) and r.get("id") and r.get("id") not in remaining_ids:
                victim_ids.add(r.get("id"))
        if victim_ids:
            logs = [r for r in logs if not (isinstance(r, dict) and r.get("id") in victim_ids)]

    # Persist logs and updated session buffer bytes
    logs.extend(new_rows)
    _save("browser_logs.json", logs)

    sess["log_buffer_bytes"] = max(0, int(used - freed + approx_new_bytes))
    sess["updated_at"] = _iso(now)
    sessions[sess_idx] = sess
    _save("browser_sessions.json", sessions)

    return {
        "created_log_ids": [r["id"] for r in new_rows],
        "evicted_count": evicted,
        "session": {"id": sessionId, "log_buffer_bytes": sess["log_buffer_bytes"], "log_buffer_limit_bytes": limit},
        "meta": {"latency_ms": int((time.time() - start) * 1000)}
    }
